import fs from 'node:fs';
import assert from 'node:assert/strict';
const fixture = JSON.parse(fs.readFileSync('docs/data/bkl042-f6-read-only-chat-fixture.json', 'utf8'));
const schema = JSON.parse(fs.readFileSync('schemas/bkl042-f6-read-only-chat.schema.json', 'utf8'));
assert.equal(fixture.schemaVersion, schema.properties.schemaVersion.const);
assert.equal(fixture.contractType, schema.properties.contractType.const);
assert.equal(fixture.mode, schema.properties.mode.const);
assert.ok(fixture.responses.length >= 2);
assert.ok(fixture.responses.some(item => item.state === 'ANSWERED'));
assert.ok(fixture.responses.some(item => item.state === 'INSUFFICIENT_EVIDENCE'));
assert.equal(fixture.authority.consumerMode, 'READ_ONLY');
assert.equal(fixture.authority.advisoryOnly, true);
for (const key of ['actionAuthority', 'commandAuthority', 'executionAuthority', 'safetyAuthority']) assert.equal(fixture.authority[key], 'NONE');
assert.equal(fixture.authority.automaticAcceptanceAuthorized, false);
for (const response of fixture.responses) {
  assert.ok(response.citations.length > 0);
  assert.ok(response.limitations.length > 0);
}
const page = fs.readFileSync('docs/bkl042-chat/index.md', 'utf8');
const js = fs.readFileSync('docs/javascripts/bkl042-chat.js', 'utf8');
const relay = fs.readFileSync('infrastructure/bkl042-ai-relay/app.py', 'utf8');
const retrieval = fs.readFileSync('infrastructure/bkl042-ai-relay/retrieval.py', 'utf8');
const gateway = fs.readFileSync('infrastructure/bkl042-portal-gateway/app.py', 'utf8');
assert.ok(page.includes('data-bkl042-chat'));
assert.ok(page.includes('bkl042-chat-question'));
assert.ok(page.includes('proiezioni pubbliche governate'));
assert.ok(js.includes('crypto.randomUUID()'));
assert.ok(js.includes('citation.url'));
assert.ok(js.includes('correlation_id=${payload.correlation_id'));
assert.ok(js.includes('method=${payload.method_version'));
assert.ok(js.includes('textContent'));
assert.doesNotMatch(js, /evidence\s*:|citations\s*:/i);
assert.ok(page.includes('Solo consultazione'));
assert.ok(js.includes('fetch('));
assert.ok(js.includes('google.accounts.id'));
assert.ok(js.includes('dsg-bkl042-portal-gateway-183451329061.europe-west1.run.app'));
assert.ok(js.includes('command_authority'));
assert.ok(js.includes('safety_authority'));
assert.ok(relay.includes('validate_answer(answer, records)'));
assert.ok(relay.includes('"store": False'));
assert.ok(relay.includes('"command_authority": "NONE"'));
assert.ok(relay.includes('"safety_authority": "NONE"'));
assert.ok(retrieval.includes('scientific-observation-index.json'));
assert.ok(retrieval.includes('target-knowledge-read-model.json'));
assert.ok(retrieval.includes('scientific-session-catalog.json'));
assert.doesNotMatch(retrieval, /raDeg|decDeg|sourceMetricsPath|serialNumber/i);
assert.ok(gateway.includes('Never trust or forward browser-supplied evidence/citations'));
assert.ok(gateway.includes('return {key: payload[key] for key in REQUIRED_FIELDS}'));
assert.doesNotMatch(js, /tools\s*:/i);
assert.doesNotMatch(js, /OPENAI_API_KEY|secretmanager|runtime_event_published\s*:\s*true/i);
console.log('BKL-042-F6 chat PASS: Google-authenticated server retrieval contract and read-only authority verified');
